<script setup lang="ts">
const props = defineProps<{ embedded?: boolean; mode?: string }>()
const { vault, auth, shared, workspaceId, workspaceName, entries, categories, busy, error, editingVaultId, categoryVaultId, vaultOptions, entryCategory, categoryCount, resetEntryCategory, active, query, sort, mobileOpen, entryOpen, categoryOpen, deleteOpen, showPassword, deleting, deletingCategory, formError, form, categoryForm, colors, icons, categoryOptions, selectedCategory, favorites, category, title, filtered, categoryMode, editEntry, editCategory, select, saveEntry, saveCategory, favorite, askDelete, remove, copy, host, generatePassword, safeUrl, productName } = useVaultWorkspace(props)
</script>
<template>
  <div :class="['vault-shell', { embedded }]">
    <aside v-if="!embedded" :class="['vault-sidebar', { 'is-open': mobileOpen }]">
      <BrandLogo />
      <VaultSwitcher v-model="workspaceId" />
      <p class="sidebar-label">ХРАНИЛИЩЕ</p>
      <nav class="vault-nav" aria-label="Хранилище">
        <button :class="{ selected: active === 'all' }" @click="select('all')"><UIcon name="i-lucide-layout-grid" />Все пароли<span>{{ entries.length }}</span></button>
        <button :class="{ selected: active === 'favorites' }" @click="select('favorites')"><UIcon name="i-lucide-star" />Избранное<span>{{ favorites }}</span></button>
      </nav>
      <div class="sidebar-label category-label">КАТЕГОРИИ<button title="Добавить категорию" aria-label="Добавить категорию" @click="editCategory()"><UIcon name="i-lucide-plus" /></button></div>
      <nav class="vault-nav" aria-label="Категории"><button v-for="c in categories" :key="c.filterId" :class="{ selected: active === c.filterId }" @click="select(c.filterId)"><UIcon :name="c.icon" :style="{ color: c.color }" /><span class="nav-category-name">{{ c.name }}<small v-if="workspaceId === 'all'">{{ c.vaultName }}</small></span><span>{{ categoryCount(c) }}</span></button></nav>
      <button class="add-category" @click="editCategory()"><UIcon name="i-lucide-plus" />Новая категория</button>
      <div class="sidebar-bottom"><div class="encryption-card"><span class="encryption-icon"><UIcon name="i-lucide-shield-check" /></span><strong>Под надёжной защитой</strong><p>Личное — только для вас.<br>Общее — для участников.</p><span class="encryption-tag"><i /> AES-256-GCM</span></div><NuxtLink to="/admin" class="sidebar-admin"><UIcon name="i-lucide-settings-2" />Панель управления<UIcon name="i-lucide-arrow-up-right" /></NuxtLink><div class="sidebar-user"><span class="user-avatar">{{ auth.user?.email?.[0]?.toUpperCase() }}</span><span><strong>Мой аккаунт</strong><small>{{ auth.user?.email }}</small></span><button title="Выйти" aria-label="Выйти" @click="auth.logout()"><UIcon name="i-lucide-log-out" /></button></div></div>
    </aside>
    <button v-if="mobileOpen" class="sidebar-scrim" aria-label="Закрыть меню" @click="mobileOpen = false" />
    <main class="vault-main">
      <header v-if="!embedded" class="vault-topbar"><div class="breadcrumb"><button class="mobile-menu" aria-label="Открыть меню" @click="mobileOpen = !mobileOpen"><UIcon name="i-lucide-menu" /></button><UIcon name="i-lucide-house" /><span>{{ workspaceName }}</span><UIcon name="i-lucide-chevron-right" /><strong>{{ title }}</strong></div><div class="topbar-actions"><span class="secure-status"><i />Хранилище открыто</span><UButton color="neutral" variant="ghost" icon="i-lucide-download" aria-label="Скачать зашифрованную копию личного хранилища" title="Копия личного хранилища" @click="vault.exportEncrypted()" /><UButton color="neutral" variant="ghost" icon="i-lucide-lock-keyhole" label="Заблокировать" size="sm" @click="vault.lock()" /></div></header>
      <div class="vault-content">
        <div v-if="embedded" class="embedded-switcher"><VaultSwitcher v-model="workspaceId" /></div>
        <UAlert v-if="shared.loading && !shared.groups.length" class="mb-5" color="neutral" title="Загружаем общие хранилища…" />
        <div v-if="!embedded" class="welcome-line"><span class="eyebrow">ПОРЯДОК В ЦИФРОВОЙ ЖИЗНИ</span><span class="vault-date">Ваше безопасное пространство</span></div>
        <div class="page-heading"><div><h1>{{ categoryMode ? 'Категории' : title }}<span class="title-dot">.</span></h1><p>{{ categoryMode ? 'Организуйте доступы так, как удобно вам.' : 'Все важные доступы — в одном надёжном месте.' }}</p></div><div class="heading-actions"><UButton v-if="category(active) && !categoryMode" color="neutral" variant="outline" icon="i-lucide-pencil" aria-label="Изменить категорию" @click="editCategory(category(active))" /><UButton v-if="category(active) && !categoryMode" color="neutral" variant="outline" icon="i-lucide-trash-2" aria-label="Удалить категорию" @click="askDelete(category(active)!, true)" /><UButton size="lg" icon="i-lucide-plus" :label="categoryMode ? 'Новая категория' : 'Добавить пароль'" @click="categoryMode ? editCategory() : editEntry()" /></div></div>
        <div v-if="!embedded" class="stats-grid"><div class="stat"><span class="stat-icon violet"><UIcon name="i-lucide-key-round" /></span><div><small>Всего паролей</small><strong>{{ entries.length.toString().padStart(2, '0') }}</strong></div><span class="stat-caption">В вашем хранилище</span></div><div class="stat"><span class="stat-icon amber"><UIcon name="i-lucide-star" /></span><div><small>В избранном</small><strong>{{ favorites.toString().padStart(2, '0') }}</strong></div><span class="stat-caption">Всегда под рукой</span></div><div class="stat"><span class="stat-icon green"><UIcon name="i-lucide-folders" /></span><div><small>Категорий</small><strong>{{ categories.length.toString().padStart(2, '0') }}</strong></div><span class="stat-caption">Всё на своих местах</span></div></div>
        <UAlert v-if="error" class="mb-5" color="error" variant="soft" :description="error" />
        <template v-if="categoryMode"><div class="category-grid"><article v-for="c in categories" :key="c.filterId" class="category-tile"><span class="category-icon" :style="{ color: c.color, background: `${c.color}12` }"><UIcon :name="c.icon" /></span><div><h3>{{ c.name }}</h3><small class="text-slate-400">{{ c.vaultName }}</small><p>{{ categoryCount(c) }} записей</p></div><UButton color="neutral" variant="ghost" icon="i-lucide-pencil" aria-label="Изменить" @click="editCategory(c)" /><UButton color="neutral" variant="ghost" icon="i-lucide-trash-2" aria-label="Удалить" @click="askDelete(c, true)" /></article></div></template>
        <template v-else>
          <div class="filter-bar"><UInput v-model="query" icon="i-lucide-search" placeholder="Найти пароль, сайт или логин…" aria-label="Поиск по хранилищу" size="lg" class="vault-search" /><div class="filter-right"><span>{{ filtered.length }} записей</span><USelect v-model="sort" :items="[{ label: 'Сначала новые', value: 'updated' }, { label: 'По названию', value: 'title' }]" aria-label="Сортировка" size="lg" /></div></div>
          <div v-if="filtered.length" class="credential-grid"><article v-for="entry in filtered" :key="`${entry.vaultId}/${entry.id}`" class="credential-card"><div class="credential-card-top"><span class="service-avatar" :style="{ color: entryCategory(entry)?.color || '#64748b', background: `${entryCategory(entry)?.color || '#64748b'}12` }">{{ entry.title.slice(0, 1).toUpperCase() }}</span><button :class="['favorite-button', { 'is-favorite': entry.favorite }]" :aria-label="entry.favorite ? 'Убрать из избранного' : 'В избранное'" :disabled="busy" @click="favorite(entry)"><UIcon name="i-lucide-star" /></button></div><button class="credential-title" @click="editEntry(entry)">{{ entry.title }}</button><a v-if="safeUrl(entry.url)" :href="safeUrl(entry.url)" target="_blank" rel="noopener noreferrer" class="credential-domain">{{ host(entry.url) }}<UIcon name="i-lucide-arrow-up-right" /></a><span v-else class="credential-domain">Приложение или сервис</span><div class="credential-fields"><div><span>Логин</span><strong>{{ entry.username || 'Не указан' }}</strong><button :disabled="!entry.username" aria-label="Скопировать логин" @click="copy(entry.username)"><UIcon name="i-lucide-copy" /></button></div><div><span>Пароль</span><strong class="password-dots">••••••••••••</strong><button aria-label="Скопировать пароль" @click="copy(entry.password)"><UIcon name="i-lucide-copy" /></button></div></div><div class="credential-origin" :class="{ 'is-shared': entry.vaultId !== 'personal' }" :title="entry.vaultName"><UIcon :name="entry.vaultId === 'personal' ? 'i-lucide-user-round' : 'i-lucide-users'" />{{ entry.vaultId === 'personal' ? 'Личное' : entry.vaultName }}</div><div class="credential-footer"><span class="category-badge"><i :style="{ background: entryCategory(entry)?.color || '#94a3b8' }" />{{ entryCategory(entry)?.name || 'Без категории' }}</span><div><button aria-label="Изменить карточку" @click="editEntry(entry)"><UIcon name="i-lucide-pencil" /></button><button aria-label="Удалить карточку" @click="askDelete(entry)"><UIcon name="i-lucide-trash-2" /></button></div></div></article><button class="new-card" @click="editEntry()"><span><UIcon name="i-lucide-plus" /></span><strong>Ещё один пароль</strong><p>Пусть всё будет под рукой</p></button></div>
          <div v-else class="empty-vault"><div class="empty-illustration"><div class="orbit orbit-one" /><div class="orbit orbit-two" /><span class="floating-key"><UIcon name="i-lucide-key-round" /></span><span class="empty-lock"><UIcon name="i-lucide-lock-keyhole" /></span><span class="floating-check"><UIcon name="i-lucide-check" /></span></div><span class="eyebrow">{{ query ? 'ПОИСК ПО ХРАНИЛИЩУ' : 'НАЧНИТЕ С ПЕРВОГО СЕКРЕТА' }}</span><h2>{{ query ? 'Ничего не нашлось' : active === 'favorites' ? 'Самое важное — рядом' : 'Здесь будут ваши пароли' }}</h2><p>{{ query ? 'Попробуйте другое название, логин или адрес сайта.' : active === 'favorites' ? 'Нажмите на звёздочку в карточке, чтобы добавить её в избранное.' : 'Добавьте первый доступ к сайту или приложению. Мы позаботимся о порядке и защите.' }}</p><UButton v-if="!query && active !== 'favorites'" size="lg" icon="i-lucide-plus" label="Добавить первый пароль" @click="editEntry()" /><UButton v-if="query" color="neutral" variant="outline" label="Сбросить поиск" @click="query = ''" /><div class="empty-features"><span><UIcon name="i-lucide-shield-check" />{{ workspaceId === 'personal' ? 'Сквозное шифрование' : 'Шифрование данных' }}</span><span><UIcon name="i-lucide-folder" />Удобные категории</span><span><UIcon name="i-lucide-sparkles" />Генератор паролей</span></div></div>
        </template>
        <div v-if="!embedded" class="vault-tip"><span><UIcon name="i-lucide-lightbulb" /></span><p><strong>Маленькая привычка — большая защита.</strong> Используйте уникальный пароль для каждого сервиса. Генератор поможет его придумать.</p><UIcon name="i-lucide-sparkles" /></div>
        <footer v-if="!embedded" class="vault-footer"><span>{{ productName }} <span class="footer-divider">/</span> Личное — для вас. Общее — для команды.</span><span><UIcon name="i-lucide-lock-keyhole" />Автоблокировка через 5 минут бездействия</span></footer>
      </div>
    </main>
    <UModal v-model:open="entryOpen" :title="form.id ? 'Изменить пароль' : 'Новый пароль'" description="Данные будут зашифрованы перед сохранением." :dismissible="!busy">
      <template #body><form id="entry-form" class="space-y-4" @submit.prevent="saveEntry"><UFormField label="Хранилище" required><USelect v-model="editingVaultId" :items="vaultOptions" @update:model-value="resetEntryCategory" :disabled="!!form.id" class="w-full" /><p class="mt-2 text-xs text-slate-500">{{ editingVaultId === 'personal' ? 'Этот пароль будет доступен только вам.' : 'Этот пароль будет доступен всем участникам хранилища.' }}</p></UFormField><UFormField label="Название" required><UInput v-model="form.title" placeholder="Например, Яндекс" class="w-full" required :maxlength="120" /></UFormField><UFormField label="Адрес сайта"><UInput v-model="form.url" placeholder="https://example.com" class="w-full" :maxlength="2000" /></UFormField><UFormField label="Логин или email"><UInput v-model="form.username" autocomplete="off" class="w-full" :maxlength="300" /></UFormField><UFormField label="Пароль" required><div class="flex gap-2"><UInput v-model="form.password" :type="showPassword ? 'text' : 'password'" autocomplete="off" class="flex-1" required :maxlength="1024" /><UButton color="neutral" variant="outline" :icon="showPassword ? 'i-lucide-eye-off' : 'i-lucide-eye'" aria-label="Показать или скрыть пароль" @click="showPassword = !showPassword" /><UButton color="neutral" variant="outline" icon="i-lucide-refresh-cw" aria-label="Сгенерировать пароль" @click="form.password = generatePassword(); showPassword = true" /></div><p class="mt-2 text-xs" :class="form.password.length >= 12 ? 'text-emerald-600' : 'text-amber-600'">{{ form.password.length >= 12 ? 'Хорошая длина пароля' : 'Рекомендуем не меньше 12 символов' }} · Генератор создаёт 24 символа</p></UFormField><UFormField label="Категория"><USelect v-model="selectedCategory" :items="categoryOptions" class="w-full" /></UFormField><UFormField label="Заметка"><UTextarea v-model="form.notes" class="w-full" placeholder="Дополнительная информация" :maxlength="10000" /></UFormField><UCheckbox v-model="form.favorite" label="Добавить в избранное" /><UAlert v-if="formError || error" color="error" :description="formError || error" /></form></template>
      <template #footer><div class="flex w-full justify-end gap-2"><UButton color="neutral" variant="outline" label="Отмена" :disabled="busy" @click="entryOpen = false" /><UButton type="submit" form="entry-form" label="Сохранить пароль" :loading="busy" /></div></template>
    </UModal>
    <UModal v-model:open="categoryOpen" :title="categoryForm.id ? 'Изменить категорию' : 'Новая категория'" description="Соберите похожие доступы вместе.">
      <template #body><form id="category-form" class="space-y-5" @submit.prevent="saveCategory"><UFormField label="Хранилище" required><USelect v-model="categoryVaultId" :items="vaultOptions" :disabled="!!categoryForm.id" class="w-full" /></UFormField><UFormField label="Название" required><UInput v-model="categoryForm.name" class="w-full" placeholder="Например, Покупки" required :maxlength="60" /></UFormField><UFormField label="Цвет"><div class="flex gap-3"><button v-for="color in colors" :key="color" type="button" :aria-label="color" :aria-pressed="categoryForm.color === color" class="color-swatch" :style="{ background: color, outline: categoryForm.color === color ? `2px solid ${color}` : 'none' }" @click="categoryForm.color = color"><UIcon v-if="categoryForm.color === color" name="i-lucide-check" /></button></div></UFormField><UFormField label="Иконка"><div class="flex flex-wrap gap-2"><UButton v-for="icon in icons" :key="icon" type="button" :icon="icon" :aria-label="icon" :color="categoryForm.icon === icon ? 'primary' : 'neutral'" :variant="categoryForm.icon === icon ? 'soft' : 'outline'" @click="categoryForm.icon = icon" /></div></UFormField><UAlert v-if="formError || error" color="error" :description="formError || error" /></form></template><template #footer><UButton type="submit" form="category-form" label="Сохранить категорию" :loading="busy" /></template>
    </UModal>
    <UModal v-model:open="deleteOpen" :title="deletingCategory ? 'Удалить категорию?' : 'Удалить пароль?'" :description="deletingCategory ? 'Карточки сохранятся и перейдут в «Без категории».' : 'Восстановить удалённую карточку будет невозможно.'"><template #body><p class="text-sm text-slate-500">{{ deleting && ('title' in deleting ? deleting.title : deleting.name) }}</p><UAlert v-if="error" color="error" :description="error" /></template><template #footer><UButton color="neutral" variant="outline" label="Отмена" @click="deleteOpen = false" /><UButton color="error" label="Удалить" :loading="busy" @click="remove" /></template></UModal>
  </div>
</template>
